import{_ as s,o as a,c as e,a2 as t}from"./chunks/framework.CCCdsIgc.js";const c=JSON.parse('{"title":"装到员工电脑","description":"","frontmatter":{},"headers":[],"relativePath":"admin/rollout.md","filePath":"admin/rollout.md"}'),l={name:"admin/rollout.md"};function n(h,i,o,r,p,d){return a(),e("div",null,[...i[0]||(i[0]=[t('<h1 id="装到员工电脑" tabindex="-1">装到员工电脑 <a class="header-anchor" href="#装到员工电脑" aria-label="Permalink to &quot;装到员工电脑&quot;">​</a></h1><h2 id="打包" tabindex="-1">打包 <a class="header-anchor" href="#打包" aria-label="Permalink to &quot;打包&quot;">​</a></h2><p>在打包用的 Windows 电脑上，进入 <code>client</code> 目录：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy Bypass </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">File </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">scripts\\publish-client.ps1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Version </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span></code></pre></div><p>生成 <code>client\\dist\\FlyknitBuddy-0.3.0.zip</code>，里面有员工端、命令行 <code>flyknit</code>、更新器、运维代理和安装程序。版本号会编进程序，以它为准。</p><h3 id="webview2-运行时" tabindex="-1">WebView2 运行时 <a class="header-anchor" href="#webview2-运行时" aria-label="Permalink to &quot;WebView2 运行时&quot;">​</a></h3><p>员工端的界面用的是 Microsoft Edge WebView2 运行时。大部分 Win10 / 11 自带并且会自动更新，但长期不联网、关了 Edge 更新的电脑（常见于 LTSC）可能<strong>没装或版本太旧</strong>，表现是装完一打开就报错。</p><p>新版员工端遇到旧运行时会尽量照常打开（只是窗口拖动改由程序处理），实在打不开会提示「WebView2 组件太旧」。要一次性给这类电脑补上：</p><ol><li><p>从微软官网的 WebView2 页面下载 <strong>Evergreen Standalone Installer（x64）</strong>，放到 <code>client\\redist\\MicrosoftEdgeWebView2RuntimeInstallerX64.exe</code>；</p></li><li><p>打包时加 <code>-WithWebView2Runtime</code>：</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">powershell </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">ExecutionPolicy Bypass </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">File </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">scripts\\publish-client.ps1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Version </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.3</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">WithWebView2Runtime</span></span></code></pre></div></li></ol><p>安装程序和运维代理在电脑上<strong>没装或太旧</strong>时，用包里的离线安装包静默装上（会先校验微软签名，不联网下载）；已经够新的电脑不会重复装。装完离线安装包不会留在 Program Files 里。</p><div class="warning custom-block"><p class="custom-block-title">已经装好的老电脑</p><p>运维代理自己目前不会自动升级，靠它补运行时要求代理是这一版以后的。之前装的电脑，用新版安装程序覆盖安装一次即可（对话、记忆、设置都不受影响）。</p></div><p>包会大大约 170 MB，所以只在需要给老电脑补运行时的那个版本里加，之后的版本可以不加。</p><h2 id="发布" tabindex="-1">发布 <a class="header-anchor" href="#发布" aria-label="Permalink to &quot;发布&quot;">​</a></h2><p>管理后台「<strong>员工端版本</strong>」：上传 zip，版本号填同一个。上传后先是「未发布」，确认无误再点「<strong>发布</strong>」。</p><h2 id="安装-推荐-安装程序" tabindex="-1">安装（推荐：安装程序） <a class="header-anchor" href="#安装-推荐-安装程序" aria-label="Permalink to &quot;安装（推荐：安装程序）&quot;">​</a></h2><ol><li>同一页点「<strong>下载员工端安装包</strong>」，格式选「安装程序 .exe」，可以起个名字（比如「三车间」）；</li><li>把 <code>FlyknitBuddy-Setup-x.y.z.exe</code> 拷到员工电脑双击，输入一次管理员密码。安装程序会： <ul><li>把员工端装到 <code>C:\\Program Files\\FlyknitBuddy</code>，建快捷方式，把命令行 <code>flyknit</code> 加入系统 PATH；</li><li>装好运维代理（Windows 服务，负责以后的自动升级），用安装包里的凭证注册，不用填注册密钥；</li></ul></li><li>员工登录：加了域的电脑点「授权登录」，没加域的输入 Windows 账号和开机密码。</li></ol><p>批量安装：<code>FlyknitBuddy-Setup-x.y.z.exe /S</code> 静默安装，可以放进组策略启动脚本或 SCCM。</p><p>每下载一次安装包生成一张安装凭证，「已下载的安装包」里能看到每个包登录了几台电脑；包外泄了点「停用」，已登录的电脑不受影响。</p><h2 id="自动升级" tabindex="-1">自动升级 <a class="header-anchor" href="#自动升级" aria-label="Permalink to &quot;自动升级&quot;">​</a></h2><p>发布新版本后，员工电脑定时检查、后台下载并校验；员工点「重启升级」或关掉程序后自动换好。替换失败会自动回滚到旧版本。</p><h3 id="找出不会自动升级的电脑" tabindex="-1">找出不会自动升级的电脑 <a class="header-anchor" href="#找出不会自动升级的电脑" aria-label="Permalink to &quot;找出不会自动升级的电脑&quot;">​</a></h3><p>自动升级靠运维代理。下面两类电脑<strong>不会自动升级</strong>，在管理后台「设备」里用筛选按钮能一次找出来：</p><table tabindex="0"><thead><tr><th>筛选</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>代理未安装</td><td>用了很早的安装包、免安装版，或者代理连不上服务器没注册上</td><td>用最新的安装程序覆盖安装一次；设备详情里有排查说明</td></tr><tr><td>免安装版</td><td>员工从产品页下的 zip，解压就用，本身就不带代理</td><td>用安装程序覆盖安装一次，员工的数据在各自的 <code>%APPDATA%\\Flyknit</code>，不受影响</td></tr></tbody></table><p>不想再有人装免安装版：「员工端版本」页的「产品页下载」里勾选「<strong>只提供安装程序</strong>」，产品页就只剩安装程序（本页的「下载员工端安装包」不受影响，IT 照样能下 zip）。</p><p>设备详情里还能看到这台电脑的<strong>安装方式</strong>和 <strong>WebView2 版本</strong>，界面打不开时先看这里。员工端要升级到这一版之后才会上报，老版本显示「—」。</p><h2 id="协议与隐私" tabindex="-1">协议与隐私 <a class="header-anchor" href="#协议与隐私" aria-label="Permalink to &quot;协议与隐私&quot;">​</a></h2><p>《用户协议》《隐私政策》有一份按本系统实际数据处理方式写的默认文本，在管理后台「协议与隐私」修改。改完后员工下次登录要同意新版本。建议请法务看一遍再发布。</p>',27)])])}const g=s(l,[["render",n]]);export{c as __pageData,g as default};
